style.css:
@-moz-document domain("roblox.com") {
html,
  body#rbx-body,
  #wrap,
  #container-main,
  #HomeContainer {
    background-image: url("https://i.pinimg.com/originals/46/26/6f/46266fda018fa0e7627f840ccc0ef0fe.gif") !important;
    background-position: center center !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-color: transparent !important;
  }

  .home-container {
    background-color: transparent !important;
  }

  #header,
  #header .rbx-navbar-header,
  #header .rbx-nav-collapse {
    background-color: #D87532 !important;
  }

  #header a,
  #header .font-header-2 {
    color: #FFFFFF !important;
  }
}
